parameters.jsCode:
// Extract failure data
const input = $input.first().json;
const body = input.body || {};
const data = body.data || {};

if (!data.subscription_id) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'Missing subscription_id',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    stripe_subscription_id: data.subscription_id,
    stripe_customer_id: data.customer_id,
    invoice_id: data.invoice_id,
    amount_due: data.amount_due || 0,
    currency: data.currency || 'eur',
    attempt_count: data.attempt_count || 1,
    event_id: body.event_id
  }
}];

// Check result and prepare notification
const dbResult = $input.first().json;
const prevData = $('Extract Data').first().json;

if (!dbResult || !dbResult.id) {
  return [{
    json: {
      found: false,
      success: true,
      message: 'Subscription not found',
      stripe_subscription_id: prevData.stripe_subscription_id
    }
  }];
}

// Format amount for display
const amountDisplay = (prevData.amount_due / 100).toFixed(2);
const currencySymbol = prevData.currency === 'eur' ? '€' : '$';

return [{
  json: {
    found: true,
    user_id: dbResult.id,
    discord_user_id: dbResult.discord_user_id,
    plan: dbResult.subscription_plan,
    stripe_customer_id: dbResult.stripe_customer_id,
    stripe_subscription_id: prevData.stripe_subscription_id,
    amount_display: currencySymbol + amountDisplay,
    amount_due: prevData.amount_due,
    currency: prevData.currency,
    attempt_count: prevData.attempt_count,
    event_id: prevData.event_id
  }
}];

